import re


def eval_expression(expr):
    """Evaluate an arithmetic expression with +, -, *, /, and parentheses."""

    if not isinstance(expr, str):
        raise TypeError("expr must be a string")

    token_pattern = re.compile(
        r"\s*(?:(\d+(?:\.\d*)?|\.\d+)|([+\-*/()]))"
    )

    tokens = []
    position = 0

    while position < len(expr):
        match = token_pattern.match(expr, position)

        if not match:
            if expr[position:].strip() == "":
                break
            raise SyntaxError(f"Invalid character at position {position}")

        number, operator = match.groups()
        tokens.append(float(number) if "." in number else int(number))
        if operator:
            tokens.append(operator)

        position = match.end()

    index = 0

    def peek():
        return tokens[index] if index < len(tokens) else None

    def parse_expression():
        nonlocal index
        value = parse_term()

        while peek() in ("+", "-"):
            operator = tokens[index]
            index += 1
            right = parse_term()
            value = value + right if operator == "+" else value - right

        return value

    def parse_term():
        nonlocal index
        value = parse_factor()

        while peek() in ("*", "/"):
            operator = tokens[index]
            index += 1
            right = parse_factor()

            if operator == "*":
                value *= right
            else:
                if right == 0:
                    raise ZeroDivisionError("division by zero")
                value /= right

        return value

    def parse_factor():
        nonlocal index

        # Support unary plus and minus, e.g. -3 and -(2 + 1)
        if peek() == "+":
            index += 1
            return parse_factor()

        if peek() == "-":
            index += 1
            return -parse_factor()

        if peek() == "(":
            index += 1
            value = parse_expression()

            if peek() != ")":
                raise SyntaxError("Missing closing parenthesis")

            index += 1
            return value

        value = peek()
        if isinstance(value, (int, float)):
            index += 1
            return value

        raise SyntaxError("Expected a number or opening parenthesis")

    result = parse_expression()

    if index != len(tokens):
        raise SyntaxError(f"Unexpected token: {tokens[index]}")

    return result
```

Example:

```python
print(eval_expression("3 + 4 * (2 - 1)"))  # 7
print(eval_expression("-2 * (3 + 1)"))      # -8
```

